cssCode:
.fluid-bg {
  position: absolute; width: 100%; height: 100%;
  overflow: hidden; filter: blur(40px); z-index: 0;
}
.fluid-blob {
  position: absolute; border-radius: 50%;
  animation: fluidMove 10s infinite alternate ease-in-out;
  opacity: 0.8;
}
.blob-1 { width: 200px; height: 200px; background: #ff007f; top: -50px; left: -50px; }
.blob-2 { width: 250px; height: 250px; background: #6c63ff; bottom: -100px; right: -50px; animation-delay: -3s; }
.blob-3 { width: 150px; height: 150px; background: #00ffcc; top: 50%; left: 50%; animation-delay: -6s; }

@keyframes fluidMove {
  0% { transform: translate(0, 0) scale(1); }
  50% { transform: translate(50px, -50px) scale(1.2); }
  100% { transform: translate(-50px, 50px) scale(0.9); }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;display:flex;align-items:center;justify-content:center;overflow:hidden;';

const fluidWrap = document.createElement('div');
fluidWrap.className = 'fluid-bg';

for(let i=1; i<=3; i++){
  const blob = document.createElement('div');
  blob.className = `fluid-blob blob-${i}`;
  fluidWrap.appendChild(blob);
}

const text = document.createElement('h2');
text.innerText = 'FLUID SIMULATION';
// BUG FIXED HERE: Added position relative and z-index 10
text.style.cssText = 'color:#fff; font-family:sans-serif; z-index:10; font-weight:bold; letter-spacing:3px; position:relative;';

c.appendChild(fluidWrap);
c.appendChild(text);
